# number_guessing_game.py

import random

def generate_secret_number(min_range, max_range):
    """Generates a random number within the specified range."""
    return random.randint(min_range, max_range)

def get_user_guess():
    """Prompts the user for a guess and validates the input."""
    while True:
        try:
            guess = int(input("Enter your guess: "))
            return guess
        except ValueError:
            print("Invalid input. Please enter a valid number.")

def check_guess(secret_number, user_guess):
    """Checks if the user's guess is correct, too high, or too low."""
    if user_guess == secret_number:
        return "correct"
    elif user_guess < secret_number:
        return "too_low"
    else:
        return "too_high"

def play_game():
    """Main function to handle the game flow."""
    print("Welcome to the Number Guessing Game!")
    min_range = 1
    max_range = 100
    attempts = 7

    secret_number = generate_secret_number(min_range, max_range)
    print(f"\nI'm thinking of a number between {min_range} and {max_range}.")

